import styled from '@emotion/styled';

export const InputSearchContainer = styled.div({
  display: 'flex',
  alignItems: 'center',
  gap: '0.5rem',
  width: '512px',
  height: '40px',
  borderRadius: '2rem',
  padding: '0.5rem 1rem',
  border: 'none',
  backgroundColor: '#1414140A',
});

export const InputSearchInput = styled.input({
  all: 'unset',
  width: '100%',
  color: 'rgba(92, 92, 92, 1)',
  fontFamily: 'Work Sans',
  fontWeight: '500',
  fontSize: '16px',
  lineHeight: '24px',
  letterSpacing: '0px',
});

export const InputSearchIcon = styled.img({
  width: '18px',
  height: '18px',
  color: 'rgba(92, 92, 92, 1)',
});

export const InputSearchClearIcon = styled.img<{ visible: boolean }>(
  ({ visible }) => ({
    display: visible ? 'block' : 'none',
    width: '24px',
    height: '24px',
    backgroundColor: 'rgba(20, 20, 20, 0.56)',
    borderRadius: '50%',
    padding: '7px',
    cursor: 'pointer',
    transition: 'all 0.3s ease',
    '&:hover': {
      backgroundColor: 'rgba(20, 20, 20, 0.76)',
    },
  }),
);
